import java.util.Scanner;

public class ProblemE {

	private static final long M = 998244353;

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		long m = in.nextLong();
		long n = in.nextLong();
		long l = in.nextLong();
		long r = in.nextLong();
		in.close();

		long totalCount = m * n;
		long segmentLength = r - l + 1;

		long powerResult = computePower(segmentLength, totalCount);
		if (totalCount % 2 == 1) {
			System.out.println(powerResult);
		} else {
			if (segmentLength % 2 == 0)
				System.out.println((powerResult * modularInverse(2, M)) % M);
			else
				System.out.println(((powerResult + 1) % M * modularInverse(2, M)) % M);
		}
	}

	public static long computePower(long base, long exponent) {
		long result = 1;
		long mod = M;
		while (exponent > 0) {
			if ((exponent & 1) == 1) {
				result = (result * base) % mod;
			}
			base = (base * base) % mod;
			exponent >>= 1;
		}
		return result;
	}

	public static long modularInverse(long a, long m) {
		return computePower(a, m - 2);
	}
}
